SELECT s.customer,COUNT(DISTINCT s.name) AS invoice_count,SUM(s.net_total) AS net_total,SUM(s.tax_amount) AS tax_amount,SUM(s.grand_total) AS grand_total FROM "tabSales Invoice" s WHERE s.docstatus=1 AND (%(company)s='' OR s.company=%(company)s) AND (%(from_date)s='' OR s.posting_date>=%(from_date)s) AND (%(to_date)s='' OR s.posting_date<=%(to_date)s) GROUP BY s.customer ORDER BY grand_total DESC
